1	package contractsentinel
2	
3	import (
4		"os"
5		"path/filepath"
6		"sort"
7		"strings"
8		"testing"
9	)
10	
11	// 本文件围绕比较功能的一项业务回归口径：新报告缩小检查范围、完全移除某条
12	// 带缺陷的旧规则时，输出必须为该标识保留一个“移除规则”条目——而不是仅凭
13	// 缺陷总数下降就把这条旧缺陷记成“已消除缺陷”。规则不再接受检查，并不等于
14	// 后续检查确认缺陷已修复：移除条目只保留旧侧，旧侧必须仍是归档中的完整规则
15	// 定义、检查状态（发现缺陷）和原始缺陷记录；缺席的新侧为 null，不能补造
16	// “通过”结论或缺陷记录。汇总中移除规则数计入这一条，已消除缺陷数不能因此
17	// 增加；两侧缺陷总数只数各自归档中实际存在的缺陷，不抹掉旧侧缺陷。
18	//
19	// 同一份比较结果中保留一条仍在新报告接受检查的规则作为对照：定义完全一致、
20	// 发现缺陷 -> 通过归为“已消除缺陷”，通过侧 finding 为 null。两条规则即使引用
21	// 同一个不变式名，也按各自规则标识独立呈现，互不接收对方的旧证据。
22	//
23	// 所有用例都走 BuildReport -> SaveReport -> DiffStore 的正常归档与读回路径，
24	// 比较的是同一产物（同一名称、同一内容哈希）的两份可正常读取的归档报告。
25	
26	// removedRuleEvidence 刻意包含中文、换行与前后空白；移除不得改写旧证据。
27	const removedRuleEvidence = "  旧反例：该检查已被移出范围\n  reentrancy 路径第二行  "
28	
29	// removedPairRules 构造同一份产物上的两条规则：removed-id 将在新报告中完全
30	// 缺席，kept-id 仍接受检查。两者刻意引用同一个不变式名，回归保障必须按规则
31	// 标识、而非按不变式名归属证据与结论。
32	func removedPairRules() []Rule {
33		return []Rule{
34			{
35				ID:        "removed-reentrancy",
36				Kind:      "static",
37				Severity:  "high",
38				Invariant: "shared-reentrancy-invariant",
39				Version:   "7.3.0",
40			},
41			{
42				ID:        "kept-reentrancy",
43				Kind:      "static",
44				Severity:  "medium",
45				Invariant: "shared-reentrancy-invariant",
46				Version:   "2.0.4",
47			},
48		}
49	}
50	
51	// assertFindingBinding 校验一条缺陷记录仍指向归档时的产物哈希、规则标识、版本
52	// 及原始证据（中文、换行与前后空白逐字保留），且严重级别与不变式名取自规则。
53	func assertFindingBinding(t *testing.T, where string, f *ReportFinding, hash string, rule Rule, evidence string) {
54		t.Helper()
55		if f == nil {
56			t.Fatalf("%s: defect finding must be preserved", where)
57		}
58		if f.ArtifactHash != hash {
59			t.Errorf("%s: artifact hash = %q, want %q", where, f.ArtifactHash, hash)
60		}
61		if f.RuleID != rule.ID {
62			t.Errorf("%s: rule id = %q, want %q", where, f.RuleID, rule.ID)
63		}
64		if f.Version != rule.Version {
65			t.Errorf("%s: version = %q, want %q (must stay the archived version)", where, f.Version, rule.Version)
66		}
67		if f.Severity != rule.Severity {
68			t.Errorf("%s: severity = %q, want %q", where, f.Severity, rule.Severity)
69		}
70		if f.Invariant != rule.Invariant {
71			t.Errorf("%s: invariant = %q, want %q", where, f.Invariant, rule.Invariant)
72		}
73		if f.Evidence != evidence {
74			t.Errorf("%s: evidence = %q, want %q verbatim", where, f.Evidence, evidence)
75		}
76	}
77	
78	// saveRemovedBeforeReport 落盘基准报告：两条规则都为发现缺陷，各自带自己的
79	// 反例证据；证据中的中文、换行和前后空白随检查说明原样归档。
80	func saveRemovedBeforeReport(t *testing.T, dir string, artifact Artifact) (Report, []Rule) {
81		t.Helper()
82		hash := ArtifactHash(artifact)
83		rules := removedPairRules()
84		report := saveCheckReport(t, dir, artifact, rules, []CheckRecord{
85			{ArtifactHash: hash, RuleID: rules[0].ID, Version: rules[0].Version, Status: StatusDefect, Note: removedRuleEvidence},
86			{ArtifactHash: hash, RuleID: rules[1].ID, Version: rules[1].Version, Status: StatusDefect, Note: "  保留规则的旧反例\n第二行  "},
87		})
88		return report, rules
89	}
90	
91	// TestDiffRemovedDefectRuleIsRemovedNotResolved 是核心回归用例：带缺陷的旧
92	// 规则在新报告规则列表中完全缺席，必须记为“移除规则”而非“已消除缺陷”，旧侧
93	// 完整保留、新侧为 null；同报告中定义一致的对照规则记为“已消除缺陷”。
94	func TestDiffRemovedDefectRuleIsRemovedNotResolved(t *testing.T) {
95		dir := t.TempDir()
96		artifact := sampleArtifact()
97		hash := ArtifactHash(artifact)
98	
99		before, rules := saveRemovedBeforeReport(t, dir, artifact)
100		removedRule := rules[0]
101		keptRule := rules[1]
102	
103		// 新报告只保留对照规则（定义完全一致）并复跑通过；被移除规则完全缺席。
104		after := saveRuleChangeCheckReport(t, dir, artifact, keptRule, StatusPass, "")
105	
106		// 两份归档必须能独立读回：基准侧两条真实缺陷，新侧无缺陷。
107		loadedBefore, err := LoadReport(dir, before.ReportID)
108		if err != nil {
109			t.Fatalf("load before: %v", err)
110		}
111		loadedAfter, err := LoadReport(dir, after.ReportID)
112		if err != nil {
113			t.Fatalf("load after: %v", err)
114		}
115		if len(loadedBefore.Findings) != 2 || len(loadedAfter.Findings) != 0 {
116			t.Fatalf("archived findings = %d/%d, want 2/0", len(loadedBefore.Findings), len(loadedAfter.Findings))
117		}
118		ruleIDsBefore := map[string]bool{}
119		for _, r := range loadedBefore.Rules {
120			ruleIDsBefore[r.ID] = true
121		}
122		if !ruleIDsBefore[removedRule.ID] {
123			t.Fatalf("baseline must contain %s", removedRule.ID)
124		}
125	
126		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
127		if err != nil {
128			t.Fatalf("diff must succeed when a defect rule is absent from the new report: %v", err)
129		}
130	
131		// 比较方向与报告标识按归档选择保留；同一产物不标记为变化。
132		if diff.Before.ReportID != before.ReportID || diff.After.ReportID != after.ReportID {
133			t.Errorf("refs = %q/%q, want %q/%q", diff.Before.ReportID, diff.After.ReportID, before.ReportID, after.ReportID)
134		}
135		if diff.ArtifactHashChanged || diff.ArtifactNameChanged {
136			t.Error("same artifact must not be flagged changed")
137		}
138	
139		// 每个标识只出现一次，共两条结果，且按规则标识排列。
140		if len(diff.Results) != 2 {
141			t.Fatalf("results = %d, want 2: %+v", len(diff.Results), diff.Results)
142		}
143		ids := []string{}
144		for _, r := range diff.Results {
145			ids = append(ids, r.RuleID)
146		}
147		if !sort.StringsAreSorted(ids) {
148			t.Errorf("results not sorted by rule id: %v", ids)
149		}
150		seen := map[string]int{}
151		for _, r := range diff.Results {
152			seen[r.RuleID]++
153		}
154		if seen[removedRule.ID] != 1 || seen[keptRule.ID] != 1 {
155			t.Fatalf("each id must appear exactly once: %v", seen)
156		}
157	
158		// --- 被移除的缺陷规则 ---
159		removed := entryByID(t, diff, removedRule.ID)
160		if removed.Change != ChangeRuleRemoved {
161			t.Fatalf("removed rule change = %q, want %q", removed.Change, ChangeRuleRemoved)
162		}
163		if removed.After != nil {
164			t.Fatalf("absent new side must be null, got %+v", removed.After)
165		}
166		if removed.Before == nil {
167			t.Fatal("removed rule must keep its old side")
168		}
169		assertRuleFields(t, "removed before side", removed.Before.Rule, removedRule, StatusDefect, removedRuleEvidence)
170		assertFindingBinding(t, "removed before side", removed.Before.Finding, hash, removedRule, removedRuleEvidence)
171	
172		// --- 仍在检查的对照规则：定义一致、缺陷 -> 通过 ---
173		kept := entryByID(t, diff, keptRule.ID)
174		if kept.Change != ChangeResolvedDefect {
175			t.Fatalf("kept rule change = %q, want %q", kept.Change, ChangeResolvedDefect)
176		}
177		if kept.Before == nil || kept.After == nil {
178			t.Fatal("resolved rule must carry both sides")
179		}
180		assertRuleFields(t, "kept before side", kept.Before.Rule, keptRule, StatusDefect, "  保留规则的旧反例\n第二行  ")
181		assertRuleFields(t, "kept after side", kept.After.Rule, keptRule, StatusPass, "")
182		assertFindingBinding(t, "kept before side", kept.Before.Finding, hash, keptRule, "  保留规则的旧反例\n第二行  ")
183		if kept.After.Finding != nil {
184			t.Errorf("passing kept-rule side must carry no finding: %+v", kept.After.Finding)
185		}
186	
187		// --- 留下的规则绝不能接收到被移除规则的旧证据 ---
188		if kept.Before.Finding != nil && kept.Before.Finding.ArtifactHash != hash {
189			t.Errorf("kept finding hash = %q, want %q", kept.Before.Finding.ArtifactHash, hash)
190		}
191		if removed.Before.Finding != nil && kept.Before.Finding != nil &&
192			removed.Before.Finding.Evidence == kept.Before.Finding.Evidence {
193			t.Error("each rule must keep its own evidence; kept rule inherited the removed rule's evidence")
194		}
195	
196		// --- 汇总：移除计入一，消除计入一；不能把移除算成消除 ---
197		s := diff.Summary
198		if s.RemovedRules != 1 {
199			t.Errorf("removedRules = %d, want 1", s.RemovedRules)
200		}
201		if s.ResolvedDefects != 1 {
202			t.Errorf("resolvedDefects = %d, want 1", s.ResolvedDefects)
203		}
204		if s.NewDefects != 0 || s.StatusChanges != 0 || s.NoteChanges != 0 ||
205			s.NoChange != 0 || s.AddedRules != 0 || s.ChangedRules != 0 {
206			t.Errorf("every other count must be zero: %+v", s)
207		}
208		// 两侧缺陷总数只数各自归档中实际存在的缺陷：旧侧 2、新侧 0。
209		if s.BeforeDefects != 2 || s.AfterDefects != 0 {
210			t.Errorf("defect totals = %d/%d, want 2/0 (actual archived findings)", s.BeforeDefects, s.AfterDefects)
211		}
212	
213		// 比较是只读操作：两份归档内容与标识保持原样，证据逐字落盘（JSON 中
214		// 换行转义为 \n），中文、前后空白不被修剪。
215		for _, id := range []string{before.ReportID, after.ReportID} {
216			data, err := os.ReadFile(filepath.Join(dir, id+".json"))
217			if err != nil {
218				t.Fatal(err)
219			}
220			if !strings.Contains(string(data), `"reportId":"`+id+`"`) {
221				t.Errorf("archive %s must keep its own id", id)
222			}
223		}
224		beforeBytes, err := os.ReadFile(filepath.Join(dir, before.ReportID+".json"))
225		if err != nil {
226			t.Fatal(err)
227		}
228		wantEscaped := `"evidence":"  旧反例：该检查已被移出范围\n  reentrancy 路径第二行  "`
229		if !strings.Contains(string(beforeBytes), wantEscaped) {
230			t.Errorf("baseline archive must keep the raw evidence verbatim:\n%s", string(beforeBytes))
231		}
232	}
233	
234	// TestDiffRemovedDefectRuleAgainstEmptyNewReport 新报告没有任何规则时同样是
235	// 合法输入：旧侧这条缺陷规则仍按移除处理，新侧缺陷总数为零，不报错也不推断
236	// 为修复。
237	func TestDiffRemovedDefectRuleAgainstEmptyNewReport(t *testing.T) {
238		dir := t.TempDir()
239		artifact := sampleArtifact()
240		hash := ArtifactHash(artifact)
241	
242		removedRule := removedPairRules()[0]
243		before := saveRuleChangeCheckReport(t, dir, artifact, removedRule, StatusDefect, removedRuleEvidence)
244		// 新报告零规则：合法归档，rules 与 findings 均为空。
245		after := saveCheckReport(t, dir, artifact, nil, nil)
246	
247		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
248		if err != nil {
249			t.Fatalf("diff against a rule-less new report must succeed: %v", err)
250		}
251		if len(diff.Results) != 1 {
252			t.Fatalf("results = %d, want 1: %+v", len(diff.Results), diff.Results)
253		}
254		entry := diff.Results[0]
255		if entry.RuleID != removedRule.ID || entry.Change != ChangeRuleRemoved {
256			t.Fatalf("entry = %q/%q, want %q/%q", entry.RuleID, entry.Change, removedRule.ID, ChangeRuleRemoved)
257		}
258		if entry.After != nil {
259			t.Errorf("absent new side must be null: %+v", entry.After)
260		}
261		assertRuleFields(t, "before side", entry.Before.Rule, removedRule, StatusDefect, removedRuleEvidence)
262		assertFindingBinding(t, "before side", entry.Before.Finding, hash, removedRule, removedRuleEvidence)
263	
264		s := diff.Summary
265		if s.RemovedRules != 1 {
266			t.Errorf("removedRules = %d, want 1", s.RemovedRules)
267		}
268		if s.ResolvedDefects != 0 || s.NewDefects != 0 {
269			t.Errorf("removal must not count as a defect transition: %+v", s)
270		}
271		if s.BeforeDefects != 1 || s.AfterDefects != 0 {
272			t.Errorf("defect totals = %d/%d, want 1/0", s.BeforeDefects, s.AfterDefects)
273		}
274	}
275	
276	// TestDiffRemovedAndResolvedIndependentOfArchiveOrder 归档中的排列顺序不影响
277	// 归属：无论基准侧两条规则以何种顺序存储、新报告对照规则放在哪里，被移除
278	// 规则与已消除规则都按标识独立分类。
279	func TestDiffRemovedAndResolvedIndependentOfArchiveOrder(t *testing.T) {
280		dir := t.TempDir()
