1	package contractsentinel
2	
3	import (
4		"os"
5		"path/filepath"
6		"sort"
7		"strings"
8		"testing"
9	)
10	
11	// 本文件回归保护“基准报告发现缺陷，新报告规则仍在却没有任何检查结论”的比较
12	// 场景：同一份合约产物、同一条规则（标识、版本及其余定义完全一致），新报告既
13	// 没有该规则的外部检查记录，也没有它引用的不变式布尔值时，规则状态只能是
14	// “未检查”，比较必须归为“检查状态变化”，绝不能因为新侧没有缺陷就记成“已消除
15	// 缺陷”。基准侧的缺陷与证据原样保留（产物哈希、规则版本、严重级别、不变式名
16	// 称都不变），新侧保留完整规则但缺陷记录为空。基准缺陷的两种既有来源——外部
17	// 检查器的反例说明、不变式值为 false 时生成的证据——必须得到相同分类；说明中
18	// 的中文、换行与前后空格逐字保留，不因新侧缺少结论而被清空、缩短或替换。这里
19	// 的每一份报告都真正落盘，再经 DiffStore 完整校验读回后比较。
20	
21	// uncheckedRegressionEvidence 刻意包含中文、换行与前后空格，任何修剪或模板
22	// 替换都会被抓到。
23	const uncheckedRegressionEvidence = "  旧反例：未复检不能当作修复\n第二行证据  "
24	
25	// uncheckedRegressionRule 是两侧共用的同一条规则定义，标识、版本及其余字段
26	// 完全一致，只有这样两侧状态才允许直接比较。
27	func uncheckedRegressionRule() Rule {
28		return Rule{ID: "reentrancy-guard", Kind: "static", Severity: "high", Invariant: "no-reentrant-withdraw", Version: "1.4.2"}
29	}
30	
31	// saveMixedCheckReport 同时携带不变式布尔值与外部检查记录构建、保存并返回
32	// 报告：两类结论分属引用不同不变式的规则时这是合法输入。
33	func saveMixedCheckReport(t *testing.T, dir string, artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) Report {
34		t.Helper()
35		report, err := BuildReport(artifact, rules, invariants, checks)
36		if err != nil {
37			t.Fatal(err)
38		}
39		if err := SaveReport(dir, report); err != nil {
40			t.Fatal(err)
41		}
42		return report
43	}
44	
45	// TestDiffDefectToUncheckedIsStatusChange 覆盖核心口径：基准侧“发现缺陷”，
46	// 新报告保留同一条规则但既无外部检查记录也无不变式值（状态为“未检查”），
47	// 必须归为“检查状态变化”，而不是“已消除缺陷”。基准缺陷的两种现有来源都要
48	// 得到相同分类，且各自的证据逐字保留。
49	func TestDiffDefectToUncheckedIsStatusChange(t *testing.T) {
50		cases := []struct {
51			name string
52			// buildBefore 构造基准侧（带缺陷）报告。
53			buildBefore    func(dir string, artifact Artifact, rule Rule, hash string) Report
54			wantEvidence   string
55			wantBeforeNote string
56		}{
57			{
58				name: "external checker counterexample",
59				buildBefore: func(dir string, artifact Artifact, rule Rule, hash string) Report {
60					return saveMixedCheckReport(t, dir, artifact, []Rule{rule}, nil,
61						[]CheckRecord{{ArtifactHash: hash, RuleID: rule.ID, Version: rule.Version,
62							Status: StatusDefect, Note: uncheckedRegressionEvidence}})
63				},
64				wantEvidence:   uncheckedRegressionEvidence,
65				wantBeforeNote: uncheckedRegressionEvidence,
66			},
67			{
68				name: "invariant false generated evidence",
69				buildBefore: func(dir string, artifact Artifact, rule Rule, hash string) Report {
70					return saveMixedCheckReport(t, dir, artifact, []Rule{rule},
71						map[string]bool{rule.Invariant: false}, nil)
72				},
73				wantEvidence:   invariantEvidence("no-reentrant-withdraw"),
74				wantBeforeNote: "",
75			},
76		}
77	
78		for _, tc := range cases {
79			t.Run(tc.name, func(t *testing.T) {
80				dir := t.TempDir()
81				artifact := sampleArtifact()
82				hash := ArtifactHash(artifact)
83				rule := uncheckedRegressionRule()
84	
85				before := tc.buildBefore(dir, artifact, rule, hash)
86				// 新报告：同一条规则仍在，但没有外部检查记录、invariants 中也没有
87				// 它引用的不变式，因此规则状态为“未检查”，且没有缺陷记录。
88				after := saveMixedCheckReport(t, dir, artifact, []Rule{rule}, nil, nil)
89	
90				// 状态不同，两份报告必然具有不同的报告标识。
91				if before.ReportID == after.ReportID {
92					t.Fatal("a defect report and an unchecked report must have different report ids")
93				}
94	
95				// 比较前留存归档快照：比较全程不得改动任何已保存报告。
96				filesBefore := storeFileNames(t, dir)
97				contentsBefore := map[string]string{}
98				for _, name := range filesBefore {
99					data, err := os.ReadFile(filepath.Join(dir, name))
100					if err != nil {
101						t.Fatal(err)
102					}
103					contentsBefore[name] = string(data)
104				}
105	
106				diff, err := DiffStore(dir, before.ReportID, after.ReportID)
107				if err != nil {
108					t.Fatal(err)
109				}
110	
111				// 同一产物、同一引用方向。
112				if diff.Before.ReportID != before.ReportID || diff.After.ReportID != after.ReportID {
113					t.Errorf("refs = %q/%q, want %q/%q", diff.Before.ReportID, diff.After.ReportID, before.ReportID, after.ReportID)
114				}
115				if diff.ArtifactNameChanged || diff.ArtifactHashChanged {
116					t.Error("same artifact must not be flagged as changed")
117				}
118	
119				// 这条规则只出现一次，归为“检查状态变化”，两侧都保留完整规则。
120				if len(diff.Results) != 1 {
121					t.Fatalf("results = %d, want 1", len(diff.Results))
122				}
123				entry := diff.Results[0]
124				if entry.RuleID != rule.ID {
125					t.Fatalf("rule id = %q, want %q", entry.RuleID, rule.ID)
126				}
127				if entry.Change != ChangeStatusChanged {
128					t.Fatalf("change = %q, want %q (a missing conclusion is not a fix)",
129						entry.Change, ChangeStatusChanged)
130				}
131				if entry.Before == nil || entry.After == nil {
132					t.Fatal("a rule still present in both reports must keep both sides")
133				}
134	
135				// 两侧规则定义逐字段一致。
136				b, a := entry.Before.Rule, entry.After.Rule
137				if b.Kind != a.Kind || b.Severity != a.Severity || b.Invariant != a.Invariant ||
138					b.RequiresABI != a.RequiresABI || b.Version != a.Version {
139					t.Errorf("rule definitions must stay identical: before=%+v after=%+v", b, a)
140				}
141	
142				// 基准侧仍带原来的缺陷记录：状态、说明与证据绑定都保持原值。
143				if b.Status != StatusDefect {
144					t.Errorf("before status = %q, want %q", b.Status, StatusDefect)
145				}
146				if b.Note != tc.wantBeforeNote {
147					t.Errorf("before note = %q, want %q verbatim", b.Note, tc.wantBeforeNote)
148				}
149				if entry.Before.Finding == nil {
150					t.Fatal("baseline side must keep its original defect finding")
151				}
152				bf := entry.Before.Finding
153				if bf.ArtifactHash != hash || bf.RuleID != rule.ID || bf.Version != rule.Version ||
154					bf.Severity != rule.Severity || bf.Invariant != rule.Invariant {
155					t.Errorf("baseline finding binding = %+v, want hash=%q rule=%q version=%q severity=%q invariant=%q",
156						*bf, hash, rule.ID, rule.Version, rule.Severity, rule.Invariant)
157				}
158				if bf.Evidence != tc.wantEvidence {
159					t.Errorf("baseline evidence = %q, want %q verbatim", bf.Evidence, tc.wantEvidence)
160				}
161	
162				// 新侧规则仍在但显示“未检查”，说明为空、缺陷记录为空——既不是“通过”，
163				// 也没有继承基准侧的旧证据。
164				if a.Status != StatusUnchecked {
165					t.Errorf("after status = %q, want %q (no check record and no invariant value)",
166						a.Status, StatusUnchecked)
167				}
168				if a.Note != "" {
169					t.Errorf("unchecked after side must carry no note, got %q", a.Note)
170				}
171				if entry.After.Finding != nil {
172					t.Errorf("unchecked after side must carry no finding, got %+v", entry.After.Finding)
173				}
174	
175				// 汇总：检查状态变化一条；绝不能计成已消除缺陷或新发现缺陷；新侧
176				// 缺陷总数为零，但逐规则分类仍是状态变化而不是修复。
177				s := diff.Summary
178				if s.StatusChanges != 1 {
179					t.Errorf("statusChanges = %d, want 1", s.StatusChanges)
180				}
181				if s.ResolvedDefects != 0 {
182					t.Errorf("resolvedDefects = %d, want 0: an unchecked rule is not a resolved defect", s.ResolvedDefects)
183				}
184				if s.NewDefects != 0 {
185					t.Errorf("newDefects = %d, want 0", s.NewDefects)
186				}
187				if s.NoteChanges != 0 || s.NoChange != 0 || s.AddedRules != 0 ||
188					s.RemovedRules != 0 || s.ChangedRules != 0 {
189					t.Errorf("every other count must be zero: %+v", s)
190				}
191				if s.BeforeDefects != 1 || s.AfterDefects != 0 {
192					t.Errorf("defect totals = %d/%d, want 1/0 (per-rule classification still applies)",
193						s.BeforeDefects, s.AfterDefects)
194				}
195	
196				// 比较后的归档内容保持原样，旧证据不被清空、缩短或替换。
197				filesAfter := storeFileNames(t, dir)
198				if strings.Join(filesBefore, ",") != strings.Join(filesAfter, ",") {
199					t.Fatalf("store files changed: %v -> %v", filesBefore, filesAfter)
200				}
201				for _, name := range filesAfter {
202					data, err := os.ReadFile(filepath.Join(dir, name))
203					if err != nil {
204						t.Fatal(err)
205					}
206					if string(data) != contentsBefore[name] {
207						t.Errorf("diff modified archive %s", name)
208					}
209				}
210	
211				// 实际读回新报告：该规则确实以“未检查”落盘且没有缺陷记录；读回
212				// 基准报告仍能看到原来的证据（外部说明时逐字保留）。
213				reloadedAfter, err := LoadReport(dir, after.ReportID)
214				if err != nil {
215					t.Fatal(err)
216				}
217				if len(reloadedAfter.Rules) != 1 || reloadedAfter.Rules[0].Status != StatusUnchecked {
218					t.Errorf("reloaded after rule = %+v, want 未检查", reloadedAfter.Rules)
219				}
220				if len(reloadedAfter.Findings) != 0 {
221					t.Errorf("reloaded after report must carry no findings, got %+v", reloadedAfter.Findings)
222				}
223				reloadedBefore, err := LoadReport(dir, before.ReportID)
224				if err != nil {
225					t.Fatal(err)
226				}
227				if len(reloadedBefore.Findings) != 1 || reloadedBefore.Findings[0].Evidence != tc.wantEvidence {
228					t.Errorf("reloaded baseline evidence = %+v, want %q", reloadedBefore.Findings, tc.wantEvidence)
229				}
230			})
231		}
232	}
233	
234	// TestDiffRealFixAndUncheckedCountedPerRule 保护“真实修复”与“未检查”同时
235	// 出现时的统计：两份报告都包含两条引用不同不变式、定义不变的规则；基准侧两
236	// 条都发现缺陷，新侧一条明确通过、另一条没有任何结论（未检查）。比较必须分
237	// 别给出“已消除缺陷”和“检查状态变化”，缺陷总数从 2 变成 0，但已消除缺陷只
238	// 计 1、检查状态变化只计 1，不出现新发现缺陷；每条结果携带各自所属规则的证
239	// 据，不能把通过规则的结论套到未检查规则上，也不能用总数下降代替逐规则判断。
240	func TestDiffRealFixAndUncheckedCountedPerRule(t *testing.T) {
241		dir := t.TempDir()
242		artifact := sampleArtifact()
243		hash := ArtifactHash(artifact)
244		// fixed 走外部检查器：基准缺陷（带反例说明）-> 新侧明确通过。
245		fixed := Rule{ID: "reentrancy-guard", Kind: "static", Severity: "high", Invariant: "no-reentrant-withdraw", Version: "1.4.2"}
246		// skipped 走不变式布尔值：基准 invariant=false 缺陷 -> 新侧既无布尔值也无检查。
247		skipped := Rule{ID: "balance-monotonic", Kind: "static", Severity: "critical", Invariant: "balance-monotonic", Version: "0.9.0"}
248		rules := []Rule{fixed, skipped}
249		skippedEvidence := invariantEvidence(skipped.Invariant)
250	
251		// 基准侧：fixed 由外部检查记录判定缺陷，skipped 由 invariant=false 判定缺陷。
252		before := saveMixedCheckReport(t, dir, artifact, rules,
253			map[string]bool{skipped.Invariant: false},
254			[]CheckRecord{{ArtifactHash: hash, RuleID: fixed.ID, Version: fixed.Version,
255				Status: StatusDefect, Note: uncheckedRegressionEvidence}})
256		// 新侧：fixed 明确通过；skipped 规则仍在，但没有检查记录、invariants 中也
257		// 没有它的不变式，因此为未检查。两条规则引用不同不变式，提交合法。
258		after := saveMixedCheckReport(t, dir, artifact, rules,
259			nil,
260			[]CheckRecord{{ArtifactHash: hash, RuleID: fixed.ID, Version: fixed.Version,
261				Status: StatusPass}})
262	
263		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
264		if err != nil {
265			t.Fatal(err)
266		}
267	
268		// 每条规则一个结果，按规则标识排序。
269		if len(diff.Results) != 2 {
270			t.Fatalf("results = %d, want 2", len(diff.Results))
271		}
272		ids := make([]string, 0, len(diff.Results))
273		byID := map[string]RuleDiff{}
274		for _, r := range diff.Results {
275			ids = append(ids, r.RuleID)
276			byID[r.RuleID] = r
277		}
278		if !sort.StringsAreSorted(ids) {
279			t.Errorf("results not sorted by rule id: %v", ids)
280		}
281	
282		// 明确修复的规则：已消除缺陷，基准侧只带自己的缺陷证据，通过侧无缺陷记录。
283		gotFixed, ok := byID[fixed.ID]
284		if !ok {
285			t.Fatalf("missing result for %s", fixed.ID)
286		}
287		if gotFixed.Change != ChangeResolvedDefect {
288			t.Errorf("fixed rule change = %q, want %q", gotFixed.Change, ChangeResolvedDefect)
289		}
290		if gotFixed.Before == nil || gotFixed.After == nil {
291			t.Fatal("fixed rule must keep both sides")
292		}
293		if gotFixed.Before.Rule.Status != StatusDefect || gotFixed.After.Rule.Status != StatusPass {
294			t.Errorf("fixed statuses = %q/%q, want 发现缺陷/通过", gotFixed.Before.Rule.Status, gotFixed.After.Rule.Status)
295		}
296		if gotFixed.Before.Finding == nil || gotFixed.Before.Finding.Evidence != uncheckedRegressionEvidence ||
297			gotFixed.Before.Finding.RuleID != fixed.ID || gotFixed.Before.Finding.Invariant != fixed.Invariant ||
298			gotFixed.Before.Finding.ArtifactHash != hash || gotFixed.Before.Finding.Version != fixed.Version {
299			t.Errorf("fixed baseline must keep its own finding: %+v", gotFixed.Before.Finding)
300		}
301		if gotFixed.After.Finding != nil {
302			t.Errorf("passing side must carry no finding: %+v", gotFixed.After.Finding)
303		}
304	
305		// 缺少结论的规则：检查状态变化，基准侧保留 invariant=false 生成的证据，
306		// 新侧未检查、无说明、无缺陷记录。
307		gotSkipped, ok := byID[skipped.ID]
308		if !ok {
309			t.Fatalf("missing result for %s", skipped.ID)
310		}
311		if gotSkipped.Change != ChangeStatusChanged {
312			t.Errorf("skipped rule change = %q, want %q", gotSkipped.Change, ChangeStatusChanged)
313		}
314		if gotSkipped.Before == nil || gotSkipped.After == nil {
315			t.Fatal("a still-present unchecked rule must keep both sides")
316		}
317		if gotSkipped.Before.Rule.Status != StatusDefect || gotSkipped.After.Rule.Status != StatusUnchecked {
318			t.Errorf("skipped statuses = %q/%q, want 发现缺陷/未检查", gotSkipped.Before.Rule.Status, gotSkipped.After.Rule.Status)
319		}
320		if gotSkipped.Before.Rule.Note != "" {
321			t.Errorf("invariant-form defect carries no rule note, got %q", gotSkipped.Before.Rule.Note)
322		}
323		if gotSkipped.Before.Finding == nil || gotSkipped.Before.Finding.Evidence != skippedEvidence ||
324			gotSkipped.Before.Finding.RuleID != skipped.ID || gotSkipped.Before.Finding.Invariant != skipped.Invariant ||
325			gotSkipped.Before.Finding.Severity != skipped.Severity ||
326			gotSkipped.Before.Finding.ArtifactHash != hash || gotSkipped.Before.Finding.Version != skipped.Version {
327			t.Errorf("skipped baseline must keep its invariant-form finding: %+v", gotSkipped.Before.Finding)
328		}
329		if gotSkipped.After.Rule.Note != "" {
330			t.Errorf("unchecked side must carry no note, got %q", gotSkipped.After.Rule.Note)
331		}
332		if gotSkipped.After.Finding != nil {
333			t.Errorf("unchecked side must carry no finding, got %+v", gotSkipped.After.Finding)
334		}
335	
336		// 证据按规则标识各自归属，不能把通过规则的结论或另一条规则的证据串过来。
337		if gotFixed.Before.Finding.RuleID == gotSkipped.Before.Finding.RuleID {
338			t.Error("findings must stay bound to their own rule ids")
339		}
340		if gotFixed.Before.Finding.Evidence == skippedEvidence ||
341			gotSkipped.Before.Finding.Evidence == uncheckedRegressionEvidence {
342			t.Error("each result must carry its own rule's evidence, not the other rule's")
343		}
344	
345		// 汇总：缺陷总数 2 -> 0，但逐规则计数仍是已消除 1、状态变化 1，没有新缺陷。
346		s := diff.Summary
347		if s.ResolvedDefects != 1 || s.StatusChanges != 1 {
348			t.Errorf("resolved/statusChanges = %d/%d, want 1/1", s.ResolvedDefects, s.StatusChanges)
349		}
350		if s.NewDefects != 0 {
351			t.Errorf("newDefects = %d, want 0", s.NewDefects)
352		}
353		if s.NoteChanges != 0 || s.NoChange != 0 || s.AddedRules != 0 ||
354			s.RemovedRules != 0 || s.ChangedRules != 0 {
355			t.Errorf("every other count must be zero: %+v", s)
356		}
357		if s.BeforeDefects != 2 || s.AfterDefects != 0 {
358			t.Errorf("defect totals = %d/%d, want 2/0; the drop must not replace per-rule classification",
359				s.BeforeDefects, s.AfterDefects)
360		}
361	}
362	
363	// TestDiffUncheckedPresentRuleIsNotRemovedRule 明确区分“规则仍在但未检查”与
364	// “规则被删除”：基准侧两条缺陷规则，新报告保留其中一条但没有结论（未检查），
365	// 另一条完全不再包含。前者必须是“检查状态变化”且新侧为完整的未检查规则，后
366	// 者才是“移除规则”且新侧整体为空，两者不能混在一起。
367	func TestDiffUncheckedPresentRuleIsNotRemovedRule(t *testing.T) {
368		dir := t.TempDir()
369		artifact := sampleArtifact()
370		hash := ArtifactHash(artifact)
371		present := Rule{ID: "present-unchecked", Kind: "static", Severity: "high", Invariant: "inv-present", Version: "1.2.0"}
372		removed := Rule{ID: "gone-removed", Kind: "static", Severity: "medium", Invariant: "inv-removed", Version: "2.3.0"}
373		presentEvidence := "  保留规则的旧反例\n第二行  "
374		removedEvidence := "  被移除规则的旧反例\n第二行  "
375	
376		// 基准侧两条规则都由外部检查器判定缺陷，各自携带不同证据。
377		before := saveMixedCheckReport(t, dir, artifact, []Rule{present, removed}, nil,
378			[]CheckRecord{
379				{ArtifactHash: hash, RuleID: removed.ID, Version: removed.Version, Status: StatusDefect, Note: removedEvidence},
380				{ArtifactHash: hash, RuleID: present.ID, Version: present.Version, Status: StatusDefect, Note: presentEvidence},
381			})
382		// 新报告只保留 present，且没有它的检查记录与不变式值 -> 未检查；removed 缺席。
383		after := saveMixedCheckReport(t, dir, artifact, []Rule{present}, nil, nil)
384	
385		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
386		if err != nil {
387			t.Fatal(err)
388		}
389		if len(diff.Results) != 2 {
390			t.Fatalf("results = %d, want 2", len(diff.Results))
391		}
392		byID := map[string]RuleDiff{}
393		for _, r := range diff.Results {
394			byID[r.RuleID] = r
395		}
396	
397		// 仍在但未检查：检查状态变化，新侧是完整规则（状态未检查）而不是 null。
398		gotPresent := byID[present.ID]
399		if gotPresent.Change != ChangeStatusChanged {
400			t.Errorf("present rule change = %q, want %q", gotPresent.Change, ChangeStatusChanged)
401		}
402		if gotPresent.Before == nil || gotPresent.After == nil {
403			t.Fatal("present unchecked rule must keep both sides")
404		}
405		if gotPresent.After.Rule.ID != present.ID || gotPresent.After.Rule.Status != StatusUnchecked {
406			t.Errorf("present after side = %+v, want the full rule with 未检查", gotPresent.After.Rule)
407		}
408		if gotPresent.After.Rule.Version != present.Version || gotPresent.After.Rule.Invariant != present.Invariant {
409			t.Errorf("present after side must keep the identical definition: %+v", gotPresent.After.Rule)
410		}
411		if gotPresent.After.Finding != nil {
412			t.Errorf("unchecked side must carry no finding, got %+v", gotPresent.After.Finding)
413		}
414		if gotPresent.Before.Finding == nil || gotPresent.Before.Finding.Evidence != presentEvidence {
415			t.Errorf("present baseline must keep its own finding: %+v", gotPresent.Before.Finding)
416		}
417	
418		// 完全缺席：移除规则，新侧整体为 null，基准侧保留原缺陷记录。
419		gotRemoved := byID[removed.ID]
420		if gotRemoved.Change != ChangeRuleRemoved {
421			t.Errorf("removed rule change = %q, want %q", gotRemoved.Change, ChangeRuleRemoved)
422		}
423		if gotRemoved.After != nil {
424			t.Errorf("an absent rule must render the new side null, got %+v", gotRemoved.After)
425		}
426		if gotRemoved.Before == nil || gotRemoved.Before.Finding == nil ||
427			gotRemoved.Before.Finding.Evidence != removedEvidence {
428			t.Errorf("removed baseline must keep the original defect: %+v", gotRemoved.Before)
429		}
430	
431		// 两类计数各自独立：状态变化 1、移除规则 1，都不算已消除缺陷。
432		s := diff.Summary
433		if s.StatusChanges != 1 || s.RemovedRules != 1 {
434			t.Errorf("statusChanges/removedRules = %d/%d, want 1/1", s.StatusChanges, s.RemovedRules)
435		}
436		if s.ResolvedDefects != 0 || s.NewDefects != 0 {
437			t.Errorf("neither an unchecked rule nor a removed one is a resolved defect: %+v", s)
438		}
439		if s.BeforeDefects != 2 || s.AfterDefects != 0 {
440			t.Errorf("defect totals = %d/%d, want 2/0", s.BeforeDefects, s.AfterDefects)
441		}
442	}
