313	// 交换基准/新报告参数：引用方向与迁移方向必须随选择反转，不得固定按归档顺序。
314	func TestCLIDiffSwapBeforeAfter(t *testing.T) {
315		bin := auditBinary(t)
316		work := t.TempDir()
317		store := filepath.Join(work, "reports")
318		artifact := mixedCheckArtifact()
