321		before := auditDiffReport(t, bin, work, store, "before.json", artifact, rules, diffBeforeChecks(hash))
322		after := auditDiffReport(t, bin, work, store, "after.json", artifact, rules, diffAfterChecks(hash))
323	
324		stdout, stderr, code := runCLIDiff(t, bin, store, after.ReportID, before.ReportID)
325		if code != 0 {
326			t.Fatalf("swapped diff must succeed, exit=%d stderr=%s", code, stderr)
327		}
328		d := decodeDiff(t, stdout)
329		if d.Before.ReportID != after.ReportID || d.After.ReportID != before.ReportID {
330			t.Errorf("refs must follow flag order: before=%q after=%q", d.Before.ReportID, d.After.ReportID)
331		}
332		changeByID := map[string]string{}
333		for _, r := range d.Results {
334			changeByID[r.RuleID] = r.Change
335		}
336		if changeByID["z-new-defect"] != contractsentinel.ChangeResolvedDefect {
337			t.Errorf("reversed z-new-defect = %q, want %q", changeByID["z-new-defect"], contractsentinel.ChangeResolvedDefect)
338		}
339		if changeByID["a-resolved"] != contractsentinel.ChangeNewDefect {
340			t.Errorf("reversed a-resolved = %q, want %q", changeByID["a-resolved"], contractsentinel.ChangeNewDefect)
341		}
342		if d.Summary.NewDefects != 1 || d.Summary.ResolvedDefects != 1 {
343			t.Errorf("reversed summary = %+v", d.Summary)
344		}
345	}
346	
347	// 同一对报告重复比较必须给出字节一致的结果，命令行输出确定可复现。
348	func TestCLIDiffDeterministicOutput(t *testing.T) {
349		bin := auditBinary(t)
350		work := t.TempDir()
351		store := filepath.Join(work, "reports")
352		artifact := mixedCheckArtifact()
353		hash := mixedArtifactHash(t)
354		rules := diffRules()
355		before := auditDiffReport(t, bin, work, store, "before.json", artifact, rules, diffBeforeChecks(hash))
356		after := auditDiffReport(t, bin, work, store, "after.json", artifact, rules, diffAfterChecks(hash))
357	
358		first, _, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID)
359		if code != 0 {
360			t.Fatal("first diff must succeed")
361		}
362		second, _, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID)
363		if code != 0 {
364			t.Fatal("second diff must succeed")
365		}
366		if first != second {
367			t.Fatal("repeated diffs must render byte-identical output")
368		}
369		// 比较结果不得携带任何时间戳字段（规则 id 中的 "timeout" 字样不算）。
370		for _, key := range []string{`"time"`, `"date"`, `"timestamp"`, `"createdAt"`} {
371			if strings.Contains(first, key) {
372				t.Errorf("diff output must not contain timestamp field %s", key)
373			}
374		}
375	}
376	
377	// 任一报告不存在：非零退出、原因进 stderr、stdout 完全空白；第二份报告
378	// 出错时也不得把已读到的第一份报告当作成功结果输出。
379	func TestCLIDiffMissingReportFailsCleanly(t *testing.T) {
380		bin := auditBinary(t)
381		work := t.TempDir()
382		store := filepath.Join(work, "reports")
383		artifact := mixedCheckArtifact()
384		hash := mixedArtifactHash(t)
385		rules := diffRules()
386		existing := auditDiffReport(t, bin, work, store, "only.json", artifact, rules, diffAfterChecks(hash))
387		missing := strings.Repeat("0", 64)
388	
389		cases := []struct {
390			name   string
391			before string
392			after  string
393		}{
394			{"before missing", missing, existing.ReportID},
395			{"after missing", existing.ReportID, missing},
396			{"both missing", strings.Repeat("1", 64), missing},
397		}
398		for _, tc := range cases {
399			t.Run(tc.name, func(t *testing.T) {
400				stdout, stderr, code := runCLIDiff(t, bin, store, tc.before, tc.after)
401				if code == 0 {
402					t.Fatal("diff must exit non-zero for a missing report")
403				}
404				if !strings.Contains(stderr, "not found") {
405					t.Fatalf("stderr must report a missing report:\n%s", stderr)
406				}
407				if stdout != "" {
408					t.Fatalf("stdout must be empty on failure, got:\n%s", stdout)
409				}
410				if strings.Contains(stdout, existing.ReportID) || strings.Contains(stdout, "results") ||
411					strings.Contains(stdout, "summary") || strings.Contains(stdout, contractsentinel.StatusUnchecked) {
412					t.Fatalf("stdout must not leak a partial result or the first report:\n%s", stdout)
413				}
414			})
415		}
416	}
417	
418	// 归档目录不存在时按“报告未找到”失败，且不得顺手创建目录。
419	func TestCLIDiffMissingStoreCreatesNothing(t *testing.T) {
420		bin := auditBinary(t)
421		store := filepath.Join(t.TempDir(), "never-created")
422		id := strings.Repeat("a", 64)
423	
424		stdout, stderr, code := runCLIDiff(t, bin, store, id, id)
425		if code == 0 {
426			t.Fatal("diff against a missing store must fail")
427		}
428		if !strings.Contains(stderr, "not found") {
429			t.Fatalf("stderr must report the missing report:\n%s", stderr)
430		}
431		if stdout != "" {
432			t.Fatalf("stdout must be empty, got:\n%s", stdout)
433		}
434		if _, err := os.Stat(store); !os.IsNotExist(err) {
435			t.Fatalf("diff must not create the store directory: %v", err)
436		}
437	}
438	
439	// 非法报告标识：非零退出并说明原因，stdout 无任何结果。
440	func TestCLIDiffInvalidReportIDFailsCleanly(t *testing.T) {
441		bin := auditBinary(t)
442		work := t.TempDir()
443		store := filepath.Join(work, "reports")
444		artifact := mixedCheckArtifact()
445		hash := mixedArtifactHash(t)
446		existing := auditDiffReport(t, bin, work, store, "only.json", artifact, diffRules(), diffAfterChecks(hash))
447	
448		for _, tc := range []struct {
449			name   string
450			before string
451			after  string
452		}{
453			{"bad before", "xyz", existing.ReportID},
454			{"bad after", existing.ReportID, "ABC"},
455		} {
456			t.Run(tc.name, func(t *testing.T) {
457				stdout, stderr, code := runCLIDiff(t, bin, store, tc.before, tc.after)
458				if code == 0 {
459					t.Fatal("diff must exit non-zero for an invalid report id")
460				}
461				if !strings.Contains(stderr, "invalid report id") {
462					t.Fatalf("stderr must explain the invalid id:\n%s", stderr)
463				}
464				if stdout != "" {
465					t.Fatalf("stdout must be empty, got:\n%s", stdout)
466				}
467			})
468		}
469	}
470	
471	// 归档内容损坏（包括第二份报告）：非零退出、原因进 stderr、stdout 不出现
472	// 比较结果或第一份报告的局部成功片段，更不能把读取失败降级成“未检查”。
473	func TestCLIDiffCorruptArchiveFailsCleanly(t *testing.T) {
474		bin := auditBinary(t)
475		work := t.TempDir()
476		store := filepath.Join(work, "reports")
477		artifact := mixedCheckArtifact()
478		hash := mixedArtifactHash(t)
479		rules := diffRules()
480		good := auditDiffReport(t, bin, work, store, "good.json", artifact, rules, diffBeforeChecks(hash))
481		bad := auditDiffReport(t, bin, work, store, "bad.json", artifact, rules, diffAfterChecks(hash))
482		if err := os.WriteFile(filepath.Join(store, bad.ReportID+".json"), []byte(`{broken`), 0o644); err != nil {
483			t.Fatal(err)
484		}
485	
486		cases := []struct {
487			name   string
488			before string
489			after  string
490		}{
491			{"second report corrupt", good.ReportID, bad.ReportID},
492			{"first report corrupt", bad.ReportID, good.ReportID},
493		}
494		for _, tc := range cases {
495			t.Run(tc.name, func(t *testing.T) {
496				stdout, stderr, code := runCLIDiff(t, bin, store, tc.before, tc.after)
497				if code == 0 {
498					t.Fatal("diff must exit non-zero for a corrupted archive")
499				}
500				if !strings.Contains(stderr, "invalid JSON") {
501					t.Fatalf("stderr must describe the corrupted archive:\n%s", stderr)
502				}
503				if stdout != "" {
504					t.Fatalf("stdout must be empty on failure, got:\n%s", stdout)
505				}
506				for _, marker := range []string{good.ReportID, bad.ReportID, `"results"`, `"summary"`,
507					contractsentinel.ChangeNewDefect, contractsentinel.ChangeResolvedDefect,
508					contractsentinel.StatusUnchecked, contractsentinel.StatusDefect} {
509					if strings.Contains(stdout, marker) {
510						t.Fatalf("stdout must not leak %q on failure:\n%s", marker, stdout)
511					}
512				}
513			})
514		}
515	}
516	
517	// 比较只是读取操作：成功与失败都必须保持归档原样——不补写报告、不修复
518	// 损坏内容、不留下临时文件。
519	func TestCLIDiffNeverModifiesStore(t *testing.T) {
520		bin := auditBinary(t)
521		work := t.TempDir()
522		store := filepath.Join(work, "reports")
523		artifact := mixedCheckArtifact()
524		hash := mixedArtifactHash(t)
525		rules := diffRules()
526		before := auditDiffReport(t, bin, work, store, "before.json", artifact, rules, diffBeforeChecks(hash))
527		after := auditDiffReport(t, bin, work, store, "after.json", artifact, rules, diffAfterChecks(hash))
528	
529		snapshot := func(t *testing.T) map[string]string {
530			t.Helper()
531			names, err := listFiles(store)
532			if err != nil {
533				t.Fatal(err)
534			}
535			sort.Strings(names)
536			out := map[string]string{}
537			for _, name := range names {
538				data, err := os.ReadFile(filepath.Join(store, name))
539				if err != nil {
540					t.Fatal(err)
541				}
542				out[name] = string(data)
543			}
544			return out
545		}
546		gotKeys := func(m map[string]string) []string {
547			keys := make([]string, 0, len(m))
548			for k := range m {
549				keys = append(keys, k)
550			}
551			sort.Strings(keys)
552			return keys
553		}
554		sameSnapshot := func(t *testing.T, got, want map[string]string) {
555			t.Helper()
556			if len(got) != len(want) {
557				t.Fatalf("store file set changed: %v vs %v", gotKeys(got), gotKeys(want))
558			}
559			for name, data := range want {
560				if got[name] != data {
561					t.Errorf("archive %s modified by diff", name)
562				}
563			}
564		}
565	
566		original := snapshot(t)
567	
568		// 成功的比较不得改动任何归档。
569		if _, stderr, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID); code != 0 {
570			t.Fatalf("successful diff failed: %s", stderr)
571		}
572		sameSnapshot(t, snapshot(t), original)
573	
574		// 损坏第二份归档后，失败的比较既不修复它，也不碰其他归档。
575		badPath := filepath.Join(store, after.ReportID+".json")
576		corrupt := []byte(`{"reportId":"corrupt"}`)
577		if err := os.WriteFile(badPath, corrupt, 0o644); err != nil {
578			t.Fatal(err)
579		}
580		if _, stderr, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID); code == 0 {
581			t.Fatalf("diff against corrupted archive must fail: %s", stderr)
582		}
583		names, err := listFiles(store)
584		if err != nil {
585			t.Fatal(err)
586		}
587		if len(names) != len(original) {
588			t.Fatalf("failure changed the store file set: %v", names)
589		}
590		kept, err := os.ReadFile(badPath)
591		if err != nil {
592			t.Fatal(err)
593		}
594		if !bytes.Equal(kept, corrupt) {
595			t.Fatal("failed diff must not repair or rewrite the corrupted archive")
596		}
597		goodBytes, err := os.ReadFile(filepath.Join(store, before.ReportID+".json"))
598		if err != nil {
599			t.Fatal(err)
600		}
601		if string(goodBytes) != original[before.ReportID+".json"] {
602			t.Fatal("failed diff modified the untouched first report")
603		}
604	}
