// 不变式名，回归保障必须按规则标识、而非按不变式名归属证据与结论。
func addedPairRules() []Rule {
	return []Rule{
		{
			ID:        "added-reentrancy",
			Kind:      "static",
			Severity:  "critical",
			Invariant: "shared-reentrancy-invariant",
			Version:   "8.1.0",
		},
